import { v } from "convex/values";
import { query } from "./_generated/server";

export const getDashboardForUser = query({
  args: {
    userId: v.id("users"),
    limitUpdates: v.optional(v.number()),
    sinceAt: v.optional(v.number()),
    perSchoolLimit: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    const user = await ctx.db.get(args.userId);
    if (!user) throw new Error("User not found");

    const limitUpdates = Math.max(1, Math.min(200, args.limitUpdates ?? 50));
    const perSchoolLimit = Math.max(1, Math.min(20, args.perSchoolLimit ?? 5));

    const selection = await ctx.db
      .query("user_school_selections")
      .withIndex("by_user", (q) => q.eq("userId", args.userId))
      .unique();

    const schoolIds = selection?.schoolIds ?? [];

    const schools = await Promise.all(schoolIds.map((id) => ctx.db.get(id)));
    const schoolById = new Map(
      schools
        .filter((s): s is NonNullable<typeof s> => !!s)
        .map((s) => [s._id, s]),
    );

    const updates: Array<
      | {
          kind: "announcement";
          schoolId: string;
          schoolNameZh: string;
          schoolNameEn: string;
          title: string;
          url: string;
          changeType: string;
          at: number;
        }
      | {
          kind: "event";
          schoolId: string;
          schoolNameZh: string;
          schoolNameEn: string;
          title: string;
          sourceUrl: string;
          at: number;
          eventAt?: number;
          registrationOpenAt?: number;
          registrationCloseAt?: number;
          quota?: number;
          targetAdmissionYear?: string;
          confidence?: number;
        }
    > = [];

    for (const schoolId of schoolIds) {
      const school = schoolById.get(schoolId);
      if (!school) continue;

      const anns = await ctx.db
        .query("announcements")
        .withIndex("by_school", (q) => q.eq("schoolId", schoolId))
        .order("desc")
        .take(perSchoolLimit);

      for (const a of anns) {
        updates.push({
          kind: "announcement",
          schoolId: String(a.schoolId),
          schoolNameZh: school.nameZh,
          schoolNameEn: school.nameEn,
          title: a.title,
          url: a.url,
          changeType: a.changeType,
          at: a.lastSeenAt,
        });
      }

      const evs = await ctx.db
        .query("events")
        .withIndex("by_school", (q) => q.eq("schoolId", schoolId))
        .order("desc")
        .take(perSchoolLimit);

      const now = Date.now();
      for (const e of evs) {
        const effectiveAt =
          typeof e.eventAt === "number"
            ? e.eventAt
            : typeof e.registrationCloseAt === "number"
              ? e.registrationCloseAt
              : null;

        // Only show future events (or unknown-dated events) on the dashboard.
        if (effectiveAt !== null && effectiveAt < now) {
          continue;
        }

        updates.push({
          kind: "event",
          schoolId: String(e.schoolId),
          schoolNameZh: school.nameZh,
          schoolNameEn: school.nameEn,
          title: e.title,
          sourceUrl: e.sourceUrl,
          at: e.updatedAt,
          eventAt: e.eventAt,
          registrationOpenAt: e.registrationOpenAt,
          registrationCloseAt: e.registrationCloseAt,
          quota: e.quota,
          targetAdmissionYear: e.targetAdmissionYear,
          confidence: e.confidence,
        });
      }
    }

    updates.sort((a, b) => b.at - a.at);
    const limited = updates.slice(0, limitUpdates);

    const sinceAt = args.sinceAt;
    const sinceCounts =
      sinceAt !== undefined
        ? {
            total: limited.filter((u) => u.at >= sinceAt).length,
            announcements: limited.filter(
              (u) => u.kind === "announcement" && u.at >= sinceAt,
            ).length,
            events: limited.filter((u) => u.kind === "event" && u.at >= sinceAt)
              .length,
          }
        : null;

    const latestMonitoringRun = await ctx.db
      .query("monitoring_runs")
      .order("desc")
      .take(1);

    // "Last checked" should reflect monitoring freshness for the user's selected schools.
    // Use the per-school websiteLastCheckedAt (set by monitoring) rather than snapshots,
    // because we may not snapshot every school on every run.
    const lastCheckedAt = Math.max(
      0,
      ...schools
        .filter((s): s is NonNullable<typeof s> => !!s)
        .map((s) => (typeof s.websiteLastCheckedAt === "number" ? s.websiteLastCheckedAt : 0)),
    );

    return {
      ok: true,
      user: {
        id: user._id,
        phone: user.phone,
        plan: user.plan ?? "FREE",
      },
      selection: selection
        ? {
            schoolIds: selection.schoolIds,
            lockedAt: selection.lockedAt ?? null,
            updatedAt: selection.updatedAt,
          }
        : null,
      schools: schools.filter((s): s is NonNullable<typeof s> => !!s),
      monitoring: latestMonitoringRun[0] ?? null,
      userMonitoringStatus: {
        trackedCount: schoolIds.length,
        lastCheckedAt: lastCheckedAt > 0 ? lastCheckedAt : null,
      },
      updates: limited,
      sinceCounts,
    };
  },
});

import { v } from "convex/values";
import { mutation, query, type MutationCtx } from "./_generated/server";
import type { Id } from "./_generated/dataModel";
import { normalizeSelection, getSelectionGuardOutcome } from "../shared/selectionRules";

type SaveForUserArgs = {
  userId: Id<"users">;
  schoolIds: Id<"schools">[];
};

type SaveForUserResult =
  | {
      ok: true;
      code: "OK";
      selectionId: Id<"user_school_selections">;
      lockedAt?: number;
    }
  | {
      ok: false;
      code: "UPGRADE_REQUIRED" | "FREE_LIMIT_EXCEEDED";
      message: string;
    };

export const getForUser = query({
  args: { userId: v.id("users") },
  handler: async (ctx, args) => {
    const row = await ctx.db
      .query("user_school_selections")
      .withIndex("by_user", (q) => q.eq("userId", args.userId))
      .unique();

    return row ?? null;
  },
});

export const clearForUserDev = mutation({
  args: { userId: v.id("users") },
  handler: async (ctx, args) => {
    const existing = await ctx.db
      .query("user_school_selections")
      .withIndex("by_user", (q) => q.eq("userId", args.userId))
      .unique();

    if (!existing) {
      return { ok: true, deleted: false };
    }

    await ctx.db.delete(existing._id);
    return { ok: true, deleted: true };
  },
});

export async function saveForUserInternal(
  ctx: MutationCtx,
  args: SaveForUserArgs,
): Promise<SaveForUserResult> {
  const user = await ctx.db.get(args.userId);
  if (!user) {
    throw new Error("User not found");
  }

  const plan = (user.plan ?? "FREE") as "FREE" | "PREMIUM";

  const normalizedSchoolIds = normalizeSelection(args.schoolIds);

  for (const schoolId of normalizedSchoolIds) {
    const school = await ctx.db.get(schoolId);
    if (!school) {
      throw new Error(`School not found: ${schoolId}`);
    }
  }

  const existing = await ctx.db
    .query("user_school_selections")
    .withIndex("by_user", (q) => q.eq("userId", args.userId))
    .unique();

  const now = Date.now();

  const guard = getSelectionGuardOutcome({
    plan,
    nextCount: normalizedSchoolIds.length,
    wasPreviouslySaved: !!existing,
    isLocked: !!existing?.lockedAt,
  });

  if (!guard.ok) {
    return {
      ok: false,
      code: guard.code,
      message: guard.message,
    };
  }

  if (!existing) {
    const lockedAt = plan === "FREE" ? now : undefined;
    const id = await ctx.db.insert("user_school_selections", {
      userId: args.userId,
      schoolIds: normalizedSchoolIds,
      lockedAt,
      createdAt: now,
      updatedAt: now,
    });
    return { ok: true, code: "OK", selectionId: id, lockedAt };
  }

  const lockedAt = existing.lockedAt ?? (plan === "FREE" ? now : undefined);

  await ctx.db.patch(existing._id, {
    schoolIds: normalizedSchoolIds,
    lockedAt,
    updatedAt: now,
  });

  return { ok: true, code: "OK", selectionId: existing._id, lockedAt };
}

export const saveForUser = mutation({
  args: {
    userId: v.id("users"),
    schoolIds: v.array(v.id("schools")),
  },
  handler: saveForUserInternal,
});

export type Plan = 'FREE' | 'PREMIUM';
export type SummaryCadence = 'daily' | 'weekly';

export type CadenceEligibility =
  | {
      status: 'eligible';
      plan: Plan;
      requestedCadence: SummaryCadence;
    }
  | {
      status: 'ineligible';
      reason: 'cadence_mismatch' | 'invalid_plan';
      plan?: string;
      requestedCadence: SummaryCadence;
    };

/**
 * Centralized cadence enforcement logic.
 *
 * FREE => weekly only
 * PREMIUM => daily only
 */
export function enforceCadence(
  planInput: string,
  requestedCadence: SummaryCadence
): CadenceEligibility {
  const plan = planInput as Plan;

  if (plan !== 'FREE' && plan !== 'PREMIUM') {
    return {
      status: 'ineligible',
      reason: 'invalid_plan',
      plan: planInput,
      requestedCadence,
    };
  }

  if (plan === 'FREE' && requestedCadence !== 'weekly') {
    return {
      status: 'ineligible',
      reason: 'cadence_mismatch',
      plan,
      requestedCadence,
    };
  }

  if (plan === 'PREMIUM' && requestedCadence !== 'daily') {
    return {
      status: 'ineligible',
      reason: 'cadence_mismatch',
      plan,
      requestedCadence,
    };
  }

  return { status: 'eligible', plan, requestedCadence };
}

/**
 * Convenience boolean checker for gating higher-level flows.
 */
export function isCadenceEligible(planInput: string, requestedCadence: SummaryCadence): boolean {
  return enforceCadence(planInput, requestedCadence).status === 'eligible';
}

import { describe, it, expect } from 'vitest'
import { enforceCadence } from '../shared/cadencePolicy'

describe('cadence policy', () => {
  it('FREE + daily => ineligible(cadence_mismatch)', () => {
    const res = enforceCadence('FREE', 'daily')
    expect(res.status).toBe('ineligible')
    if (res.status === 'ineligible') {
      expect(res.reason).toBe('cadence_mismatch')
    }
  })

  it('FREE + weekly => eligible', () => {
    const res = enforceCadence('FREE', 'weekly')
    expect(res.status).toBe('eligible')
  })

  it('PREMIUM + weekly => ineligible(cadence_mismatch)', () => {
    const res = enforceCadence('PREMIUM', 'weekly')
    expect(res.status).toBe('ineligible')
    if (res.status === 'ineligible') {
      expect(res.reason).toBe('cadence_mismatch')
    }
  })

  it('PREMIUM + daily => eligible', () => {
    const res = enforceCadence('PREMIUM', 'daily')
    expect(res.status).toBe('eligible')
  })

  it('invalid plan => ineligible(invalid_plan)', () => {
    const res = enforceCadence('ENTERPRISE', 'daily')
    expect(res.status).toBe('ineligible')
    if (res.status === 'ineligible') {
      expect(res.reason).toBe('invalid_plan')
    }
  })
})
